// The worker-dast manifests (workers/dast/tools.d). The fixtures in
// testdata/dast were generated by REAL runs of each manifest's command in the
// worker-dast image (built with WITH_SQLMAP=true WITH_NIKTO=true) against the
// deliberately vulnerable application in testdata/dast/vulnapp, on internal
// Docker networks with no internet route: the image on a network that
// reaches only a Squid egress proxy running deploy/egress/squid.conf, the
// application on a second network that only the proxy also joins (so every
// request went through dast-run's scope proxy and the egress proxy). See
// testdata/dast/README.md for the commands.

const dastManifests = "../../../workers/dast/tools.d"

func loadDASTSpecs(t *testing.T) map[string]PluginDef {
	t.Helper()
	entries, err := os.ReadDir(dastManifests)
	if err != nil {
		t.Fatal(err)
	}
	out := map[string]PluginDef{}
	for _, e := range entries {
		raw, err := os.ReadFile(filepath.Join(dastManifests, e.Name()))
		if err != nil {
			t.Fatal(err)
		}
		d, err := decodeManifestSpec(raw, true)
		if err != nil {
			t.Fatalf("%s: %v", e.Name(), err)
		}
		if e.Name() != d.Name+".yaml" {
			t.Errorf("%s: file name does not match the tool name %s", e.Name(), d.Name)
		}
		out[d.Key()] = d
	}
	return out
}

// dastIntrusive is the expected intrusive flag of every worker-dast tool.
var dastIntrusive = map[string]bool{
	"zap-baseline": false, "zap": true, "zap-api-scan": true, "wapiti": true, "dalfox": true, "ffuf": true, "sqlmap": true,
	"nikto": true, "testssl": false, "sslyze": false, "schemathesis": true, "arjun": true,
}

func TestDASTManifests(t *testing.T) {
	defs := loadDASTSpecs(t)
	if len(defs) != len(dastIntrusive) {
		t.Errorf("%d manifests, want %d", len(defs), len(dastIntrusive))
	}
	for key, want := range dastIntrusive {
		d, ok := defs[key]
		if !ok {
			t.Errorf("no manifest for %s", key)
			continue
		}
		sc, ok := scanners.Lookup(key)
		if !ok || !sc.AdapterAvailable || !sc.TargetOnly || sc.Family != "dast" || !scanners.ManifestRouted(key) {
			t.Errorf("%s: catalog entry %+v", key, sc)
		}
		if d.Network != "target" || d.Intrusive != want || sc.Intrusive != want || sc.Network != "target" {
			t.Errorf("%s: network %s intrusive %v (catalog %s %v), want target %v", key, d.Network, d.Intrusive, sc.Network, sc.Intrusive, want)
		}
		if d.Family != "dast" || d.LicenseSPDX == "" || d.LicenseSPDX != sc.License || d.Category != sc.Category {
			t.Errorf("%s: family %s licence %s/%s category %s/%s", key, d.Family, d.LicenseSPDX, sc.License, d.Category, sc.Category)
		}
		got, catalog := slices.Clone(d.ScanTypes), scanners.ScanTypesOf(key)
		slices.Sort(got)
		slices.Sort(catalog)
		if !slices.Equal(got, catalog) {
			t.Errorf("%s: manifest scan types %v, catalog %v", key, got, catalog)
		}
		// Every tool runs through dast-run, which confines it to the target.
		if d.Command != "/opt/pathos/dast/bin/dast-run" || len(d.Args) < 4 || d.Args[1] != "{target_url}" || d.Args[2] != "{output}" ||
			d.Args[3] != "{tmp}" || d.VersionArgs[0] != d.Args[0] || d.VersionArgs[1] != "--version" {
			t.Errorf("%s: command %s %v", key, d.Command, d.Args)
		}
		// Never part of a repository scan.
		if d.RunsOn("") || d.RunsOn("image") || d.RunsOn("artifact") || !d.RunsOn("api") {
			t.Errorf("%s: targets %v", key, d.Targets)
		}
		if strings.HasPrefix(d.Parser, "import:") {
			if _, ok := scanners.LookupImportFormat(strings.TrimPrefix(d.Parser, "import:")); !ok {
				t.Errorf("%s: unknown import format %s", key, d.Parser)
			}
		}
	}
	// API-definition tools scan API targets only and receive the document.
	for _, key := range []string{"zap-api-scan", "schemathesis"} {
		d := defs[key]
		if d.RunsOn("url") || d.Args[len(d.Args)-1] != "{openapi}" {
			t.Errorf("%s: %v %v", key, d.Targets, d.Args)
		}
	}
}

// Intrusive tools are skipped, without running anything, for targets whose
// intrusive testing is not authorized; tools that only send ordinary
// requests are not.
func TestDASTIntrusiveToolsNeedTheFlag(t *testing.T) {
	defs := loadDASTSpecs(t)
	dir := t.TempDir()
	spec := filepath.Join(dir, "openapi.yaml")
	if err := os.WriteFile(spec, []byte("openapi: 3.0.3\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	for key, d := range defs {
		kind := "url"
		if !d.RunsOn("url") {
			kind = "api"
		}
		for _, authorized := range []bool{false, true} {
			if !d.Intrusive && authorized {
				continue
			}
			tg := &JobTarget{Kind: kind, Reference: "https://app.example.test", IntrusiveAuthorized: authorized}
			// The command does not exist outside the image: a tool that gets
			// past the checks fails to start.
			skipped, err := (pluginTool{def: d, cacheDir: dir}).Run(context.Background(), RunInput{Out: filepath.Join(dir, key+".out"),
				Target: tg, TargetFile: spec})
			refused := skipped == "intrusive testing of this target is not authorized" && err == nil
			if d.Intrusive && !authorized && !refused {
				t.Errorf("%s ran without intrusive authorization: %q %v", key, skipped, err)
			}
			if (!d.Intrusive || authorized) && (refused || err == nil) {
				t.Errorf("%s: expected an attempt to run the command (authorized %v): %q %v", key, authorized, skipped, err)
			}
		}
		if s, err := (pluginTool{def: d, cacheDir: dir}).Run(context.Background(), RunInput{Out: filepath.Join(dir, "repo.out"), Src: dir}); err != nil ||
			!strings.Contains(s, "not repositories") {
			t.Errorf("%s on a repository job: %q %v", key, s, err)
		}
	}
}

// Tools that contact the target receive its rate limit.
func TestTargetToolRateLimitEnv(t *testing.T) {
	dir := t.TempDir()
	body := "name: rate\ncategory: dast\ncommand: /bin/sh\ntargets: [url]\nnetwork: target\n" +
		"args: [\"-c\", \"printf '%s %s' \\\"$PATHOS_TARGET_RATE_LIMIT\\\" \\\"$1\\\" > \\\"$0\\\"\", \"{output}\", \"{target_url}\"]\n"
	d, err := decodeManifestSpec([]byte(body), false)
	if err != nil {
		t.Fatal(err)
	}
	for rate, want := range map[int]string{0: "20", 5: "5", 100: "100", 500: "20"} {
		out := filepath.Join(dir, "out")
		if _, err := (pluginTool{def: d, cacheDir: dir}).Run(context.Background(), RunInput{Out: out,
			Target: &JobTarget{Kind: "url", Reference: "https://app.example.test", RateLimit: rate}}); err != nil {
			t.Fatal(err)
		}
		got, _ := os.ReadFile(out)
		if string(got) != want+" https://app.example.test" {
			t.Errorf("rate %d: %q", rate, got)
		}
	}
}

func TestDASTManifestsParseRealOutput(t *testing.T) {
	defs := loadDASTSpecs(t)
	cases := []struct {
		key, fixture, category string
		rules                  []string // rule ids that must be found
		min                    int
		host                   string // every finding is located on the target
	}{
		// Passive rules only: missing headers, cookie flags; no attack rule.
		{"zap-baseline", "zap-baseline.json", "dast", []string{"10038-1", "10020-1", "10010", "10202"}, 20, "http://b3-vulnapp"},
		// Active rules: reflected XSS (40012) and SQL injection (40018).
		{"zap", "zap-full-scan.json", "dast", []string{"40012", "40018", "10038-1"}, 30, "http://b3-vulnapp"},
		// API operations from the OpenAPI document.
		{"zap-api-scan", "zap-api-scan.json", "api", []string{"40033"}, 5, "http://b3-vulnapp"},
		{"wapiti", "wapiti.json", "dast", []string{"SQL Injection", "Reflected Cross Site Scripting", "Backup file"}, 5, "http://b3-vulnapp"},
		{"dalfox", "dalfox.json", "dast", []string{"xss-verified"}, 1, "http://b3-vulnapp/search"},
		{"ffuf", "ffuf.json", "dast", []string{"ffuf-match"}, 4, "http://b3-vulnapp/"},
		{"sqlmap", "sqlmap.csv", "database", []string{"sql-injection"}, 1, "http://b3-vulnapp/item"},
		{"nikto", "nikto.json", "dast", []string{"000029", "750500"}, 5, "http://b3-vulnapp/"},
		{"testssl", "testssl.json", "misconfiguration", []string{"testssl.TLS1", "testssl.TLS1_1", "testssl.cipherlist_aNULL"}, 10, "b3-vulnapp:443"},
		{"sslyze", "sslyze.json", "misconfiguration", []string{"sslyze.tls_1.0_supported", "sslyze.anonymous_cipher_suites", "sslyze.certificate_untrusted"}, 3, "b3-vulnapp:443"},
		{"arjun", "arjun.json", "dast", []string{"hidden-parameter"}, 1, "http://b3-vulnapp/hidden"},
		// Server errors and schema violations of the API operations (the
		// report locates them by operation path).
		{"schemathesis", "schemathesis.json", "api", []string{"ST101", "ST108", "ST201"}, 6, "/api/"},
	}
	for _, c := range cases {
		t.Run(c.key, func(t *testing.T) {
			d := defs[c.key]
			raw, err := os.ReadFile(filepath.Join("testdata", "dast", c.fixture))
			if err != nil {
				t.Fatal(err)
			}
			fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			if len(fs) < c.min {
				t.Fatalf("findings: %d, want at least %d", len(fs), c.min)
			}
			var rules []string
			fps := map[string]string{}
			for _, f := range fs {
				rules = append(rules, f.RuleID)
				if f.ScannerKey != c.key || f.Category != c.category || f.Fingerprint == "" || f.Title == "" {
					t.Errorf("finding: %+v", f)
				}
				if !strings.HasPrefix(f.FilePath, c.host) {
					t.Errorf("%s: location %q is not on the target", f.RuleID, f.FilePath)
				}
				if scanners.SeverityRank(f.Severity) == 0 && f.Severity != "info" {
					t.Errorf("severity %q", f.Severity)
				}
				// Several instances of one rule at one location (ZAP and
				// Wapiti report each request; "/" and "" are the same path) are
				// one finding.
				where := f.RuleID + " " + strings.TrimSuffix(f.FilePath, "/")
				if prev, ok := fps[f.Fingerprint]; ok && prev != where {
					t.Errorf("one fingerprint for %s and %s", prev, where)
				}
				fps[f.Fingerprint] = where
				loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, f.Fingerprint)
				if err != nil || loc == nil || len(loc.Raw) == 0 {
					t.Errorf("locate %s: %v", f.RuleID, err)
				}
			}
			for _, r := range c.rules {
				if !slices.Contains(rules, r) {
					t.Errorf("rule %s not found in %v", r, rules)
				}
			}
		})
	}
}

// The empty reports dast-run writes when a tool finds nothing (or skips an
// http target) parse as "no findings".
func TestDASTEmptyReports(t *testing.T) {
	defs := loadDASTSpecs(t)
	for key, body := range map[string]string{"dalfox": "[]", "testssl": "[]", "sqlmap": "Target URL,Place,Parameter,Technique(s),Note(s)\n",
		"arjun": `{"tool":"arjun","arjun":{},"records":[]}`} {
		fs, err := scanners.ParseToolOutput(key, defs[key].ToolParser(), []byte(body))
		if err != nil || len(fs) != 0 {
			t.Errorf("%s: %d findings, %v", key, len(fs), err)
		}
	}
}
